"""Validate and recover skills archives into a fresh private staging directory."""

from contextlib import contextmanager
import gzip
import os
import re
import shutil
import stat
import tarfile
import tempfile

from . import backup
from .errors import Conflict, IntegrityError, ValidationFailed

_CHUNK = 1024 * 1024
# Allow tar headers, padding and the PAX names generated by backup_hermes.
_MAX_TAR_BYTES = backup._MAX_TOTAL_BYTES + 64 * _CHUNK


class _TarReader:
    """Bound one tar metadata read as well as the total decompressed stream."""

    def __init__(self, file):
        self.file = file
        self.seek = file.seek
        self.tell = file.tell
        self.close = file.close
        self.write = file.write

    def read(self, size):
        if not 0 <= size <= _CHUNK:
            raise ValidationFailed('archive metadata exceeds size limit')
        return self.file.read(size)


@contextmanager
def _subdir(root, parts):
    fd = os.dup(root)
    try:
        for part in parts:
            child = os.open(part, backup._DIR_FLAGS, dir_fd=fd)
            os.close(fd)
            fd = child
        yield fd
    finally:
        os.close(fd)


def _inventory(archive, tar_size):
    members = {}
    files = size = 0
    for member in archive:
        name = member.name
        parts = tuple(name.split('/'))
        if (parts[0] != 'skills' or len(parts) > backup._MAX_DEPTH + 1 or
                any(part in ('', '.', '..') for part in parts) or
                any(c in '\\:' or ord(c) < 32 or 0x7f <= ord(c) <= 0x9f or 0xd800 <= ord(c) <= 0xdfff for c in name) or
                parts[:2] == ('skills', '.skillstore')):
            raise ValidationFailed('archive contains a path outside the supported skills layout')
        if parts in members or len(members) > backup._MAX_ENTRIES:
            raise ValidationFailed('archive contains duplicate or too many entries')
        if member.type == tarfile.DIRTYPE and member.size == 0:
            pass
        elif member.type in (tarfile.REGTYPE, tarfile.AREGTYPE) and not member.issparse():
            files += 1
            size += member.size
            if (member.size < 0 or member.size > backup._MAX_FILE_BYTES or files > backup._MAX_FILES or
                    size > backup._MAX_TOTAL_BYTES or member.offset_data + member.size > tar_size):
                raise ValidationFailed('archive contains a truncated or oversized file')
        else:
            raise ValidationFailed('archive may contain only ordinary files and directories')
        members[parts] = member
    root = members.get(('skills',))
    if root is None or not root.isdir():
        raise ValidationFailed('archive must contain a skills directory')
    for parts in members:
        if len(parts) > 1 and (parts[:-1] not in members or not members[parts[:-1]].isdir()):
            raise ValidationFailed('archive member is missing its parent directory')
    return members, files


def _require_tar_end(tar_data, offset, expanded):
    # tarfile may stop at an invalid header as if it were a normal end marker.
    if expanded - offset < 2 * tarfile.BLOCKSIZE or expanded % tarfile.BLOCKSIZE:
        raise ValidationFailed('archive lacks a complete tar end marker')
    tar_data.seek(offset)
    while chunk := tar_data.read(_CHUNK):
        if chunk.strip(b'\0'):
            raise ValidationFailed('archive has unexpected data after its tar members')


def _write_staging(archive, members, output):
    parent, leaf = output.rsplit('/', 1)
    parent_fd = backup._open_absolute_directory(parent, 'recovery output parent')
    try:
        backup._private_directory(parent_fd)
        try:
            os.mkdir(leaf, 0o700, dir_fd=parent_fd)
        except FileExistsError as exc:
            raise Conflict('recovery output already exists; choose a new directory') from exc
        # Output is a new, operator-private staging directory, not a live target.
        with _subdir(parent_fd, (leaf,)) as root_fd:
            for parts, member in sorted(members.items(), key=lambda item: item[0]):
                with _subdir(root_fd, parts[:-1]) as fd:
                    if member.isdir():
                        os.mkdir(parts[-1], 0o700, dir_fd=fd)
                        with _subdir(fd, (parts[-1],)) as created_directory:
                            os.fsync(created_directory)
                    else:
                        stream = archive.extractfile(member)
                        if stream is None:
                            raise ValidationFailed('archive member is not a readable file')
                        file_fd = os.open(parts[-1], backup._OUTPUT_FLAGS, 0o600, dir_fd=fd)
                        with stream, os.fdopen(file_fd, 'wb') as dst:
                            shutil.copyfileobj(stream, dst, _CHUNK)
                            if dst.tell() != member.size:
                                raise IntegrityError('restored file length does not match the archive')
                            os.fchmod(dst.fileno(), 0o700 if member.mode & 0o111 else 0o600)
                            dst.flush()
                            os.fsync(dst.fileno())
                    os.fsync(fd)
            backup._require_current_directory(output, root_fd)
        os.fsync(parent_fd)
    finally:
        os.close(parent_fd)


def restore_hermes(source: str, sha256: str, output: str) -> dict:
    """Verify an archive and restore its skills into a new directory, never merging."""
    backup._absolute_components(source, 'archive')
    backup._absolute_components(output, 'recovery output')
    if not re.fullmatch(r'[0-9a-fA-F]{64}', sha256):
        raise ValidationFailed('expected a SHA-256 digest of the backup archive')
    parent, name = source.rsplit('/', 1)
    parent_fd = backup._open_absolute_directory(parent, 'archive parent')
    try:
        fd = os.open(name, backup._FILE_FLAGS, dir_fd=parent_fd)
        with os.fdopen(fd, 'rb') as raw:
            original = os.fstat(raw.fileno())
            if (not stat.S_ISREG(original.st_mode) or original.st_nlink != 1 or original.st_uid != os.geteuid() or
                    stat.S_IMODE(original.st_mode) & 0o077 or original.st_size > _MAX_TAR_BYTES):
                raise ValidationFailed('archive must be an owner-private regular file within size limits')
            actual = backup._sha256_from_fd(raw.fileno())
            if actual != sha256.lower():
                raise IntegrityError('archive SHA-256 does not match the expected digest')
            raw.seek(0)
            with tempfile.TemporaryFile() as tar_data:
                expanded = 0
                try:
                    with gzip.GzipFile(fileobj=raw, mode='rb') as gz:
                        while chunk := gz.read(_CHUNK):
                            expanded += len(chunk)
                            if expanded > _MAX_TAR_BYTES:
                                raise ValidationFailed('archive exceeds expanded size limit')
                            tar_data.write(chunk)
                    if not (backup._same_object(original, os.fstat(raw.fileno())) and
                            backup._same_object(original, os.stat(name, dir_fd=parent_fd, follow_symlinks=False))):
                        raise IntegrityError('archive changed while restoring')
                    tar_data.seek(0)
                    with tarfile.open(fileobj=_TarReader(tar_data), mode='r:', errorlevel=2) as archive:
                        members, files = _inventory(archive, expanded)
                        _require_tar_end(tar_data, archive.offset, expanded)
                        _write_staging(archive, members, output)
                except (EOFError, gzip.BadGzipFile, tarfile.TarError) as exc:
                    raise ValidationFailed('invalid or truncated skills archive') from exc
    finally:
        os.close(parent_fd)
    return {'output': output, 'skills': output + '/skills', 'sha256': actual, 'files': files}
